PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT ?deathPlace ?deathPlaceLabel WHERE {
  {
    dbr:Veerendra dbo:deathPlace ?deathPlace
  } UNION {
    dbr:Veerendra dbp:deathPlace ?deathPlace
  }
  .
  OPTIONAL {
    ?deathPlace rdfs:label ?deathPlaceLabel .
    FILTER(lang(?deathPlaceLabel) = 'en')
  }
}

